import React from 'react';

function ShowtimeScreen({ movie, showtimes, rooms, onSelectShowtime, onBack }) {
  const lichChieuCuaPhim = showtimes.filter(st => st.movie_id === movie.id);

  return (
    <div style={{ color: '#e2e8f0', minHeight: '80vh' }}>
      <button
        className="btn mb-4 fw-bold text-white border-0"
        style={{
          background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
          boxShadow: '0 18px 30px rgba(124, 58, 237, 0.35)'
        }}
        onClick={onBack}
      >⬅ Quay lại trang chủ</button>

      <div
        className="card p-4 shadow-sm border-0"
        style={{
          background: 'rgba(15, 23, 42, 0.94)',
          border: '1px solid rgba(124, 58, 237, 0.22)',
          boxShadow: '0 28px 60px rgba(0, 0, 0, 0.30)'
        }}
      >
        <div className="d-flex align-items-start mb-3 gap-3">
          <div style={{ flex: '0 0 260px' }}>
            <img
              src={movie.image_url}
              alt={movie.title}
              style={{
                width: '100%',
                height: 380,
                objectFit: 'cover',
                borderRadius: 10,
                boxShadow: '0 20px 40px rgba(2,6,23,0.6)',
                filter: 'contrast(1.03) saturate(1.08)',
                display: 'block'
              }}
            />
          </div>
          <div style={{ flex: 1 }}>
            <div className="d-flex justify-content-between align-items-start">
              <div>
                <h3 className="fw-bold mb-1" style={{ color: '#f9a8d4', fontSize: 36, lineHeight: 1.02 }}>🎬 {movie.title}</h3>
                <p className="mb-2" style={{ color: '#cbd5e1', fontSize: 16, maxWidth: '100%', lineHeight: 1.6 }}>{movie.description}</p>
                <p className="mb-0" style={{ color: '#cbd5e1', fontSize: 15 }}>Vui lòng chọn suất chiếu phù hợp.</p>
              </div>
              <div className="text-end small">
                <div className="fw-bold" style={{ color: '#fbbf24' }}>⭐ {movie.rating}</div>
                <div className="mt-1" style={{ color: '#94a3b8' }}>👁 {movie.viewers.toLocaleString()}</div>
              </div>
            </div>
          </div>
        </div>

        <div className="row">
          {lichChieuCuaPhim.length > 0 ? (
            lichChieuCuaPhim.map((st) => (
              <div className="col-sm-6 col-md-4 mb-3" key={st.id}>
                <button
                  className="btn p-0 w-100 shadow-sm fw-bold"
                  style={{
                    border: '1px solid rgba(124, 58, 237, 0.35)',
                    backgroundColor: 'rgba(15, 23, 42, 0.88)',
                    color: '#e2e8f0',
                    minHeight: '120px',
                    padding: 0,
                    overflow: 'hidden',
                    borderRadius: 8,
                    textAlign: 'left'
                  }}
                  onClick={() => onSelectShowtime(st)}
                >
                  <div style={{ display: 'flex', gap: 12, alignItems: 'center', padding: '12px' }}>
                    <div style={{ flex: '0 0 110px' }}>
                      <img
                        src={movie.image_url}
                        alt={movie.title}
                        style={{ width: '110px', height: '82px', objectFit: 'cover', borderRadius: 8, display: 'block', filter: 'contrast(1.04) saturate(1.06)'}}
                      />
                    </div>
                    <div style={{ flex: 1 }}>
                      <div className="fs-6" style={{ color: '#94a3b8' }}>
                        🏟 Phòng: {rooms.find(r => r.id === st.room_id)?.name || 'Chưa xác định'}
                      </div>
                      <div className="fs-3 my-1" style={{ color: '#a78bfa' }}>⏰ Giờ: {st.show_time}</div>
                      <div style={{ height: 6 }} />
                      <div className="small" style={{ color: '#cbd5e1' }}>
                        Giá vé: {(st.ticket_price + (rooms.find(r => r.id === st.room_id)?.is_vip ? 50000 : 0)).toLocaleString()}đ{rooms.find(r => r.id === st.room_id)?.is_vip ? ' (VIP +50.000đ)' : ''}
                      </div>
                    </div>
                  </div>
                </button>
              </div>
            ))
          ) : (
            <div className="col-12 text-center py-4" style={{ color: '#94a3b8' }}>Hiện tại phim này chưa có lịch chiếu mới.</div>
          )}
        </div>
      </div>
    </div>
  );
}

export default ShowtimeScreen;
